using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD intrinsics to process multiple elements per cycle.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        ref float start = ref MemoryMarshal.GetReference(values);
        int length = values.Length;

        if (!Vector.IsHardwareAccelerated || length < Vector<float>.Count)
        {
            return FindMinMaxScalar(ref start, length);
        }

        int vectorSize = Vector<float>.Count;
        ref float vectorEnd = ref Unsafe.Add(ref start, length - vectorSize);

        var vMin = new Vector<float>(start);
        var vMax = vMin;

        // Process two vectors per iteration to improve ILP
        int twoVec = vectorSize * 2;
        ref float current = ref Unsafe.Add(ref start, vectorSize);

        while (Unsafe.IsAddressLessThan(ref Unsafe.Add(ref current, vectorSize), ref vectorEnd))
        {
            var v0 = new Vector<float>(current);
            var v1 = new Vector<float>(Unsafe.Add(ref current, vectorSize));
            vMin = Vector.Min(vMin, Vector.Min(v0, v1));
            vMax = Vector.Max(vMax, Vector.Max(v0, v1));
            current = ref Unsafe.Add(ref current, twoVec);
        }

        // Handle remaining full vectors
        while (!Unsafe.IsAddressGreaterThan(ref current, ref vectorEnd))
        {
            var v = new Vector<float>(current);
            vMin = Vector.Min(vMin, v);
            vMax = Vector.Max(vMax, v);
            current = ref Unsafe.Add(ref current, vectorSize);
        }

        // Process the final (possibly overlapping) vector to cover tail elements
        var vLast = new Vector<float>(vectorEnd);
        vMin = Vector.Min(vMin, vLast);
        vMax = Vector.Max(vMax, vLast);

        // Horizontal reduction
        float min = vMin[0], max = vMax[0];
        for (int i = 1; i < vectorSize; i++)
        {
            if (vMin[i] < min) min = vMin[i];
            if (vMax[i] > max) max = vMax[i];
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static (float Min, float Max) FindMinMaxScalar(ref float start, int length)
    {
        float min = start, max = start;
        for (int i = 1; i < length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }
        return (min, max);
    }
}

